/* InvoiceExpensePro Tools – one file, three reusable engines:
   1) calc()  – calculators      2) crud() – saved records (also used for invoices etc.)
   3) custom tools at the bottom (CSV, PDF, OCR, report). To add a tool, add a line to TOOLS. */
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>{const n=Number.parseFloat(v);return Number.isFinite(n)?n:0};
const CURRENCIES=new Set(['','PKR','USD','EUR','GBP','AED']);
const selectedCurrency=()=>{try{const c=localStorage.getItem('iep_currency')||'';return CURRENCIES.has(c)?c:''}catch{return''}};
const money=n=>{const currency=selectedCurrency();return currency?new Intl.NumberFormat(undefined,{style:'currency',currency,currencyDisplay:'code'}).format(num(n)):num(n).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})};
const dateKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const today=()=>dateKey(new Date());
const validDateKey=s=>/^\d{4}-\d{2}-\d{2}$/.test(s)&&dateKey(new Date(`${s}T00:00:00`))===s;
const store={get:(k,d=[])=>{try{const v=JSON.parse(localStorage.getItem('iep_'+k));return Array.isArray(d)&&!Array.isArray(v)?d:(v??d)}catch{return d}},set:(k,v)=>{try{localStorage.setItem('iep_'+k,JSON.stringify(v));return true}catch(e){alert('Could not save data. Browser storage may be full or unavailable.');return false}}};
function download(name,data,type='text/plain'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type}));a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
const toCSV=r=>r.map(x=>x.map(c=>'"'+String(c??'').replace(/"/g,'""')+'"').join(',')).join('\n');
function parseCSV(t){const rows=[];let r=[],c='',q=false;for(let i=0;i<t.length;i++){const ch=t[i];
 if(q){if(ch=='"'&&t[i+1]=='"'){c+='"';i++}else if(ch=='"')q=false;else c+=ch}
 else if(ch=='"'&&!c)q=true;else if(ch==','){r.push(c);c=''}else if(ch=='\n'||ch=='\r'){if(ch=='\r'&&t[i+1]=='\n')i++;r.push(c);rows.push(r);r=[];c=''}else c+=ch}
 if(q)throw new Error('CSV contains an unclosed quoted field.');if(c||r.length){r.push(c);rows.push(r)}return rows.filter(x=>x.some(y=>y.trim()))}
const LIBS={jspdf:['https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js','jspdf'],xlsx:['https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js','XLSX'],chart:['https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.min.js','Chart'],tesseract:['https://cdn.jsdelivr.net/npm/tesseract.js@5.0.4/dist/tesseract.min.js','Tesseract'],pdflib:['https://cdnjs.cloudflare.com/ajax/libs/pdf-lib/1.17.1/pdf-lib.min.js','PDFLib']};
const libraryPromises={};function loadLibrary(name){const [src,globalName]=LIBS[name];if(window[globalName])return Promise.resolve(true);if(libraryPromises[name])return libraryPromises[name];libraryPromises[name]=new Promise(resolve=>{const s=document.createElement('script');s.src=src;s.async=true;s.onload=()=>resolve(!!window[globalName]);s.onerror=()=>resolve(false);document.head.append(s)}).then(ok=>{if(!ok){delete libraryPromises[name];alert((name==='pdflib'?'PDF':name.toUpperCase())+' library could not be loaded. Check your internet connection and try again.')}return ok});return libraryPromises[name]}
const readFile=(f,m='text')=>new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=()=>rej(new Error('The selected file could not be read.'));r.onabort=()=>rej(new Error('File reading was cancelled.'));m=='text'?r.readAsText(f):r.readAsArrayBuffer(f)});
async function loadTextFile(file,target){if(!file)return;try{$(target).value=await readFile(file)}catch(e){alert(e.message)}}

/* ---------- Field helper: [key,label,type,options/default] ---------- */
function field([k,l,t='text',o],v){
 if(t=='area')return `<label>${l}<textarea name="${k}">${esc(v)}</textarea></label>`;
 if(t=='select')return `<label>${l}<select name="${k}">${o.map(x=>`<option ${x==v?'selected':''}>${x}</option>`).join('')}</select></label>`;
 if(t=='date'&&!v)v=today();
 return `<label>${l}<input name="${k}" type="${t}" ${t=='number'?'step="any"':''} value="${esc(v)}"></label>`}

/* ---------- Engine 1: calculators ---------- */
function calc(el,fields,run,validate=()=>true){
 el.innerHTML=`<div class=card><div class=grid>${fields.map(f=>field([f[0],f[1],'number',f[3]],f[2]??'')).join('')}</div></div><div class=card><div class=res id=out aria-live=polite></div></div>`;
 const go=()=>{const v={};el.querySelectorAll('input').forEach(i=>v[i.name]=num(i.value));if(!validate(v))return $('#out').innerHTML='<p class="note" role="alert">Check that amounts and percentages are within the valid range.</p>';
  $('#out').innerHTML=run(v).map(([a,b])=>`<div>${esc(a)}<b>${esc(b)}</b></div>`).join('')};
 el.addEventListener('input',go);el.addEventListener('change',go);go()}
const CALCS={
 profit:[[['rev','Revenue'],['cost','Cost of goods'],['exp','Other expenses']],v=>{const p=v.rev-v.cost-v.exp;return[['Net profit',money(p)],['Margin %',v.rev?money(p/v.rev*100)+'%':'–']]}],
 loss:[[['buy','Purchase / cost price'],['sell','Selling price'],['qty','Quantity',1]],v=>{const l=(v.buy-v.sell)*v.qty;return[[l>0?'Total loss':'Result (no loss)',money(Math.max(l,0))],['Loss %',v.buy?money(Math.max(l,0)/(v.buy*v.qty)*100)+'%':'–']]}],
 budget:[[['inc','Monthly income'],['rent','Rent / housing'],['food','Food'],['trans','Transport'],['bills','Bills'],['oth','Other'],['sav','Savings goal']],v=>{const s=v.rent+v.food+v.trans+v.bills+v.oth;return[['Total spending',money(s)],['Left after spending',money(v.inc-s)],['Left after savings goal',money(v.inc-s-v.sav)],['Savings rate %',v.inc?money(v.sav/v.inc*100)+'%':'–']]}],
 cashflow:[[['open','Opening balance'],['in','Cash in'],['out','Cash out']],v=>[['Net cash flow',money(v.in-v.out)],['Closing balance',money(v.open+v.in-v.out)]]],
 breakeven:[[['fixed','Fixed costs'],['price','Price per unit'],['var','Variable cost per unit']],v=>{const m=v.price-v.var;return m>0?[['Break-even units',Math.ceil(v.fixed/m)],['Break-even revenue',money(Math.ceil(v.fixed/m)*v.price)],['Contribution / unit',money(m)]]:[['Error','Price must exceed variable cost']]}],
 savings:[[['goal','Savings goal'],['cur','Current savings'],['mon','Monthly deposit'],['rate','Annual interest %']],v=>{let b=v.cur,m=0;const r=v.rate/1200;while(b<v.goal&&m<1200&&(v.mon>0||r>0)){b=b*(1+r)+v.mon;m++}return b>=v.goal?[['Months to goal',m],['Years',money(m/12)],['Final balance',money(b)]]:[['Goal not reachable','Increase monthly deposit']]}],
 tax:[[['amt','Amount'],['rate','Tax rate %',10]],v=>[['Tax',money(v.amt*v.rate/100)],['Total incl. tax',money(v.amt*(1+v.rate/100))],['If amount already includes tax: net',money(v.amt/(1+v.rate/100))]]],
 discount:[[['p','Original price'],['d','Discount %']],v=>[['Final price',money(v.p*(1-v.d/100))],['You save',money(v.p*v.d/100)]]],
 markup:[[['c','Cost'],['m','Markup %']],v=>[['Selling price',money(v.c*(1+v.m/100))],['Profit',money(v.c*v.m/100)],['Margin %',v.m?money(v.m/(100+v.m)*100)+'%':'0%']]],
 margin:[[['p','Selling price'],['c','Cost']],v=>[['Profit',money(v.p-v.c)],['Margin %',v.p?money((v.p-v.c)/v.p*100)+'%':'–'],['Markup %',v.c?money((v.p-v.c)/v.c*100)+'%':'–']]],
 commission:[[['s','Sales amount'],['r','Commission rate %'],['b','Base salary']],v=>[['Commission',money(v.s*v.r/100)],['Total earnings',money(v.b+v.s*v.r/100)]]],
 loan:[[['p','Loan amount'],['r','Annual interest %'],['y','Years',1]],v=>{const r=v.r/1200,n=v.y*12,m=r?v.p*r/(1-Math.pow(1+r,-n)):v.p/(n||1);return[['Monthly payment',money(m)],['Total paid',money(m*n)],['Total interest',money(m*n-v.p)]]}],
 salary:[[['g','Gross monthly salary'],['t','Tax %'],['a','Allowances (added)'],['d','Other deductions']],v=>{const tax=v.g*v.t/100,net=v.g-tax+v.a-v.d;return[['Tax',money(tax)],['Net monthly',money(net)],['Net yearly',money(net*12)]]}]};

/* ---------- Engine 2: saved records with add/edit/delete/export ---------- */
function crud(el,o){
 let list=store.get(o.key),edit=null,chart,searchText='',sortKey='';
 const persist=()=>{if(store.set(o.key,list))return true;list=store.get(o.key);return false};
 const val=(r,k)=>k=='total'?money(o.total(r)):k=='status'?invoiceStatus(r):r[k]??'';
 const draw=()=>{if(chart){chart.destroy();chart=null}const visible=list.map((r,i)=>({r,i})).filter(({r})=>JSON.stringify(r).toLowerCase().includes(searchText.toLowerCase())).sort((a,b)=>{if(!sortKey)return a.i-b.i;const av=sortKey==='total'?o.total?.(a.r):sortKey==='status'?invoiceStatus(a.r):a.r[sortKey]??'',bv=sortKey==='total'?o.total?.(b.r):sortKey==='status'?invoiceStatus(b.r):b.r[sortKey]??'',numeric=sortKey==='total'||o.fields.find(f=>f[0]===sortKey)?.[2]==='number';return numeric?num(av)-num(bv):String(av).localeCompare(String(bv),undefined,{numeric:true,sensitivity:'base'})});const sum=o.sum?list.reduce((s,r)=>s+num(r[o.sum]),0):list.reduce((s,r)=>s+(o.total?o.total(r):0),0);
  el.innerHTML=`${o.documentForm?o.documentForm(edit==null?null:list[edit],edit!=null):`<form class=card id=f><h3>${edit==null?'Add new':'Edit'} ${o.title}</h3><div class=grid>${o.fields.map(f=>field(f,edit!=null?list[edit][f[0]]:'')).join('')}</div><button class=btn>Save</button>${edit!=null?'<button type=button class="btn alt" id=cx>Cancel</button>':''}</form>`}${o.documentPreview?`<section class="card invoice-preview-card" id=invoicePreview aria-live=polite>${o.documentPreview(edit==null?null:list[edit])}</section>`:''}
  <div class=card><div class=bar><b>${list.length} saved${o.sum||o.total?' · Total '+money(sum):''}</b><span><button class="btn sm alt" id=ecsv>CSV</button><button class="btn sm alt" id=exls>Excel</button><button class="btn sm danger" id=eall>Delete all</button></span></div>
  <div class=grid><label>Search records<input id=recordSearch type=search value="${esc(searchText)}" placeholder="Filter by any saved field"></label><label>Sort by<select id=recordSort><option value="">Saved order</option>${o.cols.map(c=>`<option value="${esc(c)}" ${sortKey===c?'selected':''}>${o.fields.find(f=>f[0]===c)?.[1]||(c==='status'?'Status':'Total')}</option>`).join('')}</select></label></div><div class=scroll><table><thead><tr>${o.cols.map(c=>`<th>${o.fields.find(f=>f[0]==c)?.[1]||(c==='status'?'Status':'Total')}</th>`).join('')}<th>Actions</th></tr></thead><tbody>
  ${visible.map(({r,i})=>`<tr>${o.cols.map(c=>`<td>${esc(val(r,c))}</td>`).join('')}<td><button class="btn sm" data-e=${i}>Edit</button><button class="btn sm danger" data-d=${i}>Delete</button>${o.pdf?`<button class="btn sm alt" data-p=${i}>PDF</button>`:''}${o.extra?o.extra(r,i):''}</td></tr>`).join('')||`<tr><td colspan=9>${list.length?'No records match your search.':'Nothing saved yet.'}</td></tr>`}</tbody></table></div></div>${o.chart?`<div class=card>${list.some(r=>num(r[o.sum])>0)?'<div class=chart-box><canvas id=ch aria-label="Expenses by category chart"></canvas></div>':'<div class=empty-state>No expense amounts are available for a category chart.</div>'}</div>`:''}`;
  $('#f').onsubmit=e=>{e.preventDefault();const values=o.readForm?o.readForm(e.target,edit==null?null:list[edit]):Object.fromEntries(new FormData(e.target));const r=edit==null?values:{...list[edit],...values};if(o.validate&&!o.validate(r)){if(!o.validateShowsMessage)alert('Check the entered values. Amounts and quantities must be valid and non-negative.');return}edit==null?list.push(r):list[edit]=r;if(!persist()){edit=null;draw();return}edit=null;draw()};
  if(o.documentForm){const form=$('#f'),currentDraft=()=>o.readForm(form,edit==null?null:list[edit]),refresh=()=>{const draft=currentDraft();$('#invoicePreview').innerHTML=o.documentPreview(draft);form.querySelectorAll('.invoice-item-row').forEach(row=>{row.querySelector('.invoice-line-amount').textContent=money(lineAmount({q:num(row.querySelector('[name="itemQuantity"]').value),p:num(row.querySelector('[name="itemPrice"]').value)}))});const status=form.querySelector('.invoice-payment-status strong');if(status)status.textContent=invoiceStatus(draft)},validDraft=()=>{const draft=currentDraft();return form.reportValidity()&&(!o.validate||o.validate(draft))};$('#addInvoiceItem').onclick=()=>{const row=document.createElement('div');row.innerHTML=o.itemRow({d:'',q:1,p:0});$('#invoiceItems').append(row.firstElementChild);refresh()};$('#invoiceItems').onclick=e=>{const button=e.target.closest('[data-remove-item]');if(button){button.closest('.invoice-item-row').remove();refresh()}};form.addEventListener('input',refresh);form.addEventListener('change',refresh);$('#printInvoice').onclick=()=>{if(!validDraft())return;document.body.classList.add('invoice-printing');addEventListener('afterprint',()=>document.body.classList.remove('invoice-printing'),{once:true});print()};$('#downloadInvoice').onclick=()=>{if(validDraft())pdfDoc(currentDraft(),o)};refresh()}
  $('#cx')&&($('#cx').onclick=()=>{edit=null;draw()});
  $('#recordSearch').oninput=e=>{searchText=e.target.value;const pos=e.target.selectionStart;draw();const input=$('#recordSearch');input.focus();input.setSelectionRange(pos,pos)};
  $('#recordSort').onchange=e=>{sortKey=e.target.value;draw()};
  el.querySelectorAll('[data-e]').forEach(b=>b.onclick=()=>{edit=+b.dataset.e;draw();scrollTo(0,0)});
  el.querySelectorAll('[data-d]').forEach(b=>b.onclick=()=>{if(confirm('Delete this record?')){list.splice(+b.dataset.d,1);if(!persist()){draw();return}draw()}});
  el.querySelectorAll('[data-p]').forEach(b=>b.onclick=()=>pdfDoc(list[+b.dataset.p],o));
  el.querySelectorAll('[data-pay]').forEach(b=>b.onclick=()=>{const row=list[+b.dataset.pay],balance=Math.max(0,o.total(row)-invoicePaid(row));if(!balance)return alert('This invoice is already fully paid.');const entered=prompt('Payment amount received. Remaining balance: '+money(balance),String(balance));if(entered===null)return;const raw=Number(entered),amount=Math.round((raw+Number.EPSILON)*100)/100;if(!Number.isFinite(raw)||amount<=0||amount>balance+0.001)return alert('Enter an amount greater than zero and no more than the remaining balance.');const date=prompt('Payment date (YYYY-MM-DD)',today());if(date===null)return;if(!validDateKey(date))return alert('Enter a valid date as YYYY-MM-DD.');row.payments=[...(row.payments||[]),{amount,date}];if(!persist()){draw();return}draw()});
  const rows=()=>[o.cols.map(c=>o.fields.find(f=>f[0]==c)?.[1]||'Total'),...list.map(r=>o.cols.map(c=>val(r,c)))];
  $('#ecsv').onclick=()=>download(o.key+'.csv',toCSV(rows()),'text/csv');
  $('#exls').onclick=async()=>{if(!await loadLibrary('xlsx'))return;const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(rows()),'Data');XLSX.writeFile(wb,o.key+'.xlsx')};
  $('#eall').onclick=()=>{if(confirm('Delete ALL records here?')){list=[];if(!persist()){draw();return}draw()}};
  if(o.chart&&window.Chart&&list.some(r=>num(r[o.sum])>0)){const g={};list.forEach(r=>g[r[o.chart]||'Uncategorized']=(g[r[o.chart]||'Uncategorized']||0)+num(r[o.sum]));
   chart=new Chart($('#ch'),{type:'bar',options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}}},data:{labels:Object.keys(g),datasets:[{label:'Total by '+o.chart,data:Object.values(g),backgroundColor:'#087f74',borderRadius:6}]}})}};
 draw();if(o.chart&&list.some(r=>num(r[o.sum])>0)&&!window.Chart)loadLibrary('chart').then(ok=>{if(ok&&el.isConnected)draw()})}

/* ---------- Document engine (invoice, quote, receipt, PO…) built on crud ---------- */
const lines=t=>Array.isArray(t)?t.map(l=>({d:String(l?.d??l?.description??''),q:l?.q===undefined||l?.q===''?1:num(l.q??l.quantity),p:num(l?.p??l?.unitPrice)})).filter(l=>l.d.trim()):String(t||'').split('\n').map(l=>l.split('|').map(x=>x.trim())).filter(l=>l[0]).map(l=>({d:l[0],q:l[1]===undefined||l[1]===''?1:num(l[1]),p:num(l[2])}));
function nextRecurringDate(start,freq,now=new Date()){const base=new Date(`${start}T12:00:00`);if(Number.isNaN(base.getTime()))return null;const months={Monthly:1,Quarterly:3,Yearly:12}[freq],weekly=freq==='Weekly';let n=0,candidate=new Date(base);while(candidate<now&&n<500){n++;if(weekly){candidate=new Date(base);candidate.setDate(base.getDate()+7*n)}else{const monthIndex=base.getMonth()+months*n,year=base.getFullYear()+Math.floor(monthIndex/12),month=((monthIndex%12)+12)%12,day=Math.min(base.getDate(),new Date(year,month+1,0).getDate());candidate=new Date(year,month,day,12)}}return candidate}
const cents=n=>Math.round((n+Number.EPSILON)*100)/100;
const lineAmount=l=>cents(Math.max(0,l.q)*Math.max(0,l.p));
const docSubtotal=r=>cents(lines(r.items).reduce((a,l)=>a+lineAmount(l),0));
const docDiscount=r=>cents(Math.min(docSubtotal(r),Math.max(0,r.discType==='Fixed'?num(r.disc):docSubtotal(r)*num(r.disc)/100)));
const docTax=r=>cents(Math.max(0,docSubtotal(r)-docDiscount(r))*Math.max(0,num(r.tax))/100);
const docTotal=r=>cents(docSubtotal(r)-docDiscount(r)+docTax(r));
const invoicePaid=r=>Array.isArray(r.payments)?r.payments.reduce((s,p)=>s+Math.max(0,num(p.amount)),0):Math.max(0,num(r.paid));
function invoiceStatus(r){const total=docTotal(r),paid=invoicePaid(r),due=Math.max(0,total-paid);if(total<.005)return'No total';if(due<.005)return'Paid';if(r.due&&r.due<today())return paid>0?'Overdue · partial':'Overdue';return paid>0?'Partially paid':'Unpaid'}
function validateDocument(r){const entries=lines(r.items);if(!entries.length)return(alert('Add at least one invoice item.'),false);if(num(r.tax)<0||num(r.disc)<0)return(alert('Tax and discount cannot be negative.'),false);if(r.discType!=='Fixed'&&num(r.disc)>100)return(alert('Percentage discount cannot exceed 100%.'),false);if(r.discType==='Fixed'&&num(r.disc)>docSubtotal(r))return(alert('A fixed discount cannot exceed the subtotal.'),false);if(entries.some(l=>l.q<=0||l.p<0))return(alert('Item quantities must be above zero and prices cannot be negative.'),false);return true}
function invoiceItemRow(item={d:'',q:1,p:0}){return `<div class="invoice-item-row"><label class="item-description">Description<input name="itemDescription" type="text" value="${esc(item.d)}" placeholder="Product or service"></label><label>Quantity<input name="itemQuantity" type="number" min="0.01" step="any" value="${esc(item.q)}"></label><label>Unit Price<input name="itemPrice" type="number" min="0" step="0.01" value="${esc(item.p)}"></label><output class="invoice-line-amount">${money(num(item.q)*num(item.p))}</output><button type="button" class="btn sm danger remove-invoice-item" data-remove-item aria-label="Remove line item">Remove</button></div>`}
function invoiceDraft(form,record=null){const val=name=>form.elements.namedItem(name)?.value??'';return{no:val('no'),date:val('date'),due:val('due'),brandName:val('brandName'),brandEmail:val('brandEmail'),brandPhone:val('brandPhone'),brandAddress:val('brandAddress'),client:val('client'),clientEmail:val('clientEmail'),clientPhone:val('clientPhone'),clientAddress:val('clientAddress'),tax:val('tax'),discType:val('discType'),disc:val('disc'),paymentDetails:val('paymentDetails'),notes:val('notes'),payments:record?.payments,paid:record?.paid,items:[...form.querySelectorAll('.invoice-item-row')].map(row=>({d:row.querySelector('[name="itemDescription"]').value.trim(),q:row.querySelector('[name="itemQuantity"]').value,p:row.querySelector('[name="itemPrice"]').value})).filter(item=>item.d)}}
function invoicePreview(r={}){r=r||{};const itemRows=lines(r.items),status=invoiceStatus(r),subtotal=docSubtotal(r),discount=docDiscount(r),tax=docTax(r),paid=invoicePaid(r),balance=Math.max(0,docTotal(r)-paid);return `<div class="invoice-preview"><div class="invoice-preview-head"><div><p class="invoice-eyebrow">INVOICE</p><h2>${esc(r.brandName||'Your business')}</h2><p>${[r.brandAddress,r.brandEmail,r.brandPhone].filter(Boolean).map(esc).join('<br>')||'Business contact details'}</p></div><div class="invoice-preview-number"><strong>${esc(r.no||'INV-0001')}</strong><span class="invoice-status status-${status.toLowerCase().replace(/[^a-z]+/g,'-')}">${esc(status)}</span></div></div><div class="invoice-parties"><section><h3>Bill to</h3><strong>${esc(r.client||'Client name')}</strong><p>${[r.clientAddress,r.clientEmail,r.clientPhone].filter(Boolean).map(esc).join('<br>')||'Client contact details'}</p></section><section class="invoice-dates"><div><small>Issue date</small><strong>${esc(r.date||'—')}</strong></div><div><small>Due date</small><strong>${esc(r.due||'—')}</strong></div></section></div><div class="scroll invoice-preview-table"><table><thead><tr><th>Description</th><th>Quantity</th><th>Unit price</th><th>Amount</th></tr></thead><tbody>${itemRows.length?itemRows.map(l=>`<tr><td>${esc(l.d)}</td><td>${esc(l.q)}</td><td>${money(l.p)}</td><td>${money(lineAmount(l))}</td></tr>`).join(''):'<tr><td colspan="4" class="muted-cell">Your invoice items will appear here.</td></tr>'}</tbody></table></div><div class="invoice-preview-bottom"><div class="invoice-preview-notes"><h3>Payment details</h3><p>${esc(r.paymentDetails||'Add payment instructions or bank details.')}</p><h3>Notes</h3><p>${esc(r.notes||'Add a thank-you message or other notes.')}</p></div><dl class="invoice-totals"><div><dt>Subtotal</dt><dd>${money(subtotal)}</dd></div><div><dt>Discount</dt><dd>−${money(discount)}</dd></div><div><dt>Tax (${esc(r.tax||0)}%)</dt><dd>${money(tax)}</dd></div>${paid>0?`<div><dt>Paid</dt><dd>−${money(paid)}</dd></div>`:''}<div class="grand-total"><dt>${paid>0?'Balance due':'Total due'}</dt><dd>${money(balance)}</dd></div></dl></div></div>`}
function invoiceForm(record,editing){const r=record||{},items=lines(r.items);return `<form class="card invoice-form" id="f"><div class="invoice-form-heading"><div><p class="invoice-eyebrow">INVOICE WORKSPACE</p><h2>${editing?'Edit':'Create'} invoice</h2><p>Enter the details below. Your preview and totals update as you work.</p></div><span class="invoice-step">${editing?'Editing saved invoice':'New invoice'}</span></div><section class="invoice-form-section"><h3>Invoice details</h3><div class="grid invoice-meta-grid">${field(['no','Invoice number','text'],r.no||'INV-'+String(Date.now()).slice(-6))}${field(['date','Issue date','date'],r.date||today())}${field(['due','Due date','date'],r.due||'')}</div></section><section class="invoice-form-section"><div class="invoice-party-grid"><div><h3>Your business</h3><div class="grid invoice-contact-grid">${field(['brandName','Business name','text'],r.brandName||'')}${field(['brandEmail','Business email','email'],r.brandEmail||'')}${field(['brandPhone','Business phone','tel'],r.brandPhone||'')}${field(['brandAddress','Business address','area'],r.brandAddress||'')}</div></div><div><h3>Client details</h3><div class="grid invoice-contact-grid">${field(['client','Client name','text'],r.client||'')}${field(['clientEmail','Client email','email'],r.clientEmail||'')}${field(['clientPhone','Client phone','tel'],r.clientPhone||'')}${field(['clientAddress','Client address','area'],r.clientAddress||'')}</div></div></div></section><section class="invoice-form-section"><div class="invoice-section-heading"><div><h3>Line items</h3><p>Add each product or service on its own row.</p></div><button type="button" class="btn alt" id="addInvoiceItem">＋ Add item</button></div><div class="invoice-item-editor"><div class="invoice-item-head"><span>Description</span><span>Quantity</span><span>Unit price</span><span>Amount</span><span></span></div><div id="invoiceItems">${(items.length?items:[{d:'',q:1,p:0}]).map(invoiceItemRow).join('')}</div></div></section><section class="invoice-form-section"><h3>Tax, discount &amp; payment</h3><div class="grid invoice-total-inputs">${field(['tax','Tax rate (%)','number'],r.tax??0)}${field(['discType','Discount type','select',['Percent','Fixed']],r.discType||'Percent')}${field(['disc','Discount','number'],r.disc??0)}<div class="invoice-payment-status"><small>Payment status</small><strong>${esc(invoiceStatus(r))}</strong><span>Record payments after saving the invoice.</span></div></div><div class="grid invoice-notes-grid">${field(['paymentDetails','Payment details','area'],r.paymentDetails||'')}${field(['notes','Notes','area'],r.notes||'')}</div></section><div class="invoice-form-actions"><button class="btn" type="submit">${editing?'Save changes':'Save invoice'}</button><button class="btn alt" type="button" id="downloadInvoice">Download PDF</button><button class="btn alt" type="button" id="printInvoice">Print / Save as PDF</button>${editing?'<button type="button" class="btn alt" id="cx">Cancel</button>':''}</div></form>`}
function docTool(el,key,title,extra=[],pre='INV'){const invoices=['invoice','invoicepdf'].includes(key);crud(el,{key,title,pdf:true,total:docTotal,cols:['no','client','date',...(invoices?['status']:[]),'total'],docTitle:title,trackPayments:invoices,validateShowsMessage:true,
 validate:validateDocument,
 extra:invoices?(r,i)=>`<button type=button class="btn sm alt" data-pay="${i}">Record payment</button>`:undefined,
 documentForm:invoices?invoiceForm:undefined,documentPreview:invoices?invoicePreview:undefined,itemRow:invoiceItemRow,readForm:invoices?invoiceDraft:undefined,
 fields:[['no','Number','text'],['client','Client name','text'],['date','Issue date','date'],['due','Due date','date'],['items','Items – one per line: description | qty | unit price','area'],['tax','Tax %','number'],['discType','Discount type','select',['Percent','Fixed']],['disc','Discount amount / %','number'],...extra,['notes','Notes / payment details','area']]})}
function pdfDoc(r,o){if(!window.jspdf){loadLibrary('jspdf').then(ok=>ok&&pdfDoc(r,o));return}const d=new jspdf.jsPDF(),left=16,right=194;let y=0;
 const pageHeader=()=>{d.setFillColor(19,43,74);d.rect(0,0,210,30,'F');d.setTextColor(255);d.setFont('helvetica','bold');d.setFontSize(17);d.text((r.brandName||'InvoiceExpensePro Tools').toUpperCase(),left,13);d.setFont('helvetica','normal');d.setFontSize(9);const contact=[r.brandEmail,r.brandPhone,r.brandAddress].filter(Boolean).join(' · ');if(contact)d.text(d.splitTextToSize(contact,120),left,20);d.setFont('helvetica','bold');d.setFontSize(18);d.text((o.docTitle||'Invoice').toUpperCase(),right,13,{align:'right'});d.setFont('helvetica','normal');d.setFontSize(10);d.text(r.no||'',right,21,{align:'right'});d.setTextColor(36,51,72)};
 const sectionTitle=(text,x,y0)=>{d.setFont('helvetica','bold');d.setFontSize(9);d.setTextColor(8,127,116);d.text(text.toUpperCase(),x,y0);d.setTextColor(36,51,72);d.setFont('helvetica','normal')};
 const tableHead=()=>{d.setFillColor(238,243,247);d.roundedRect(left,y-5,right-left,9,1.5,1.5,'F');d.setFont('helvetica','bold');d.setFontSize(9);d.text('Description',left+2,y+1);d.text('Qty',119,y+1,{align:'right'});d.text('Unit price',153,y+1,{align:'right'});d.text('Amount',right-2,y+1,{align:'right'});d.setFont('helvetica','normal');y+=11};
 pageHeader();y=42;sectionTitle('Bill to',left,y);sectionTitle('Invoice details',124,y);y+=6;d.setFont('helvetica','bold');d.setFontSize(11);d.text(r.client||'Client',left,y);d.setFont('helvetica','normal');d.setFontSize(9);let clientLines=[r.clientAddress,r.clientEmail,r.clientPhone].filter(Boolean).flatMap(v=>d.splitTextToSize(v,88));if(clientLines.length)d.text(clientLines,left,y+6);d.text('Issued: '+(r.date||'—'),124,y);d.text('Due: '+(r.due||'—'),124,y+6);if(o.trackPayments)d.text('Status: '+invoiceStatus(r),124,y+12);y+=Math.max(20,clientLines.length*4.5+10);tableHead();
 for(const item of lines(r.items)){const desc=d.splitTextToSize(item.d,87),height=Math.max(7,desc.length*4.5+2);if(y+height>270){d.addPage();pageHeader();y=42;tableHead()}d.setFontSize(9);d.text(desc,left+2,y);d.text(String(item.q),119,y,{align:'right'});d.text(money(item.p),153,y,{align:'right'});d.text(money(lineAmount(item)),right-2,y,{align:'right'});y+=height;d.setDrawColor(220,228,236);d.line(left,y-2,right,y-2)}
 y+=8;if(y>244){d.addPage();pageHeader();y=42}sectionTitle('Payment details',left,y);const detailLines=d.splitTextToSize(r.paymentDetails||'—',82);sectionTitle('Notes',105,y);const noteLines=d.splitTextToSize(r.notes||'—',82);d.setFontSize(9);d.setTextColor(80,96,113);d.text(detailLines,left,y+6);d.text(noteLines,105,y+6);const totalsY=Math.max(y+7+Math.max(detailLines.length,noteLines.length)*4.5, y+24);if(totalsY>235){d.addPage();pageHeader();y=42}else y=totalsY;d.setTextColor(36,51,72);d.setFontSize(9);d.text('Subtotal',150,y);d.text(money(docSubtotal(r)),right,y,{align:'right'});y+=6;d.text(`Discount${r.discType==='Percent'?` (${num(r.disc)}%)`:''}`,150,y);d.text('−'+money(docDiscount(r)),right,y,{align:'right'});y+=6;d.text(`Tax (${num(r.tax)}%)`,150,y);d.text(money(docTax(r)),right,y,{align:'right'});y+=6;const paid=invoicePaid(r);if(paid>0){d.text('Paid',150,y);d.text('−'+money(paid),right,y,{align:'right'});y+=6}d.setFillColor(19,43,74);d.roundedRect(145,y,right-145,13,2,2,'F');d.setTextColor(255);d.setFont('helvetica','bold');d.setFontSize(11);d.text(paid>0?'BALANCE DUE':'TOTAL DUE',150,y+8.5);d.text(money(Math.max(0,docTotal(r)-paid)),right-3,y+8.5,{align:'right'});
 d.save((o.docTitle+'-'+(r.no||'doc')).replace(/\s+/g,'_')+'.pdf')}

/* ---------- Engine 3: custom tools ---------- */
function csvViewer(el){el.innerHTML=`<div class=card><label>CSV file<input type=file id=fi accept=".csv,text/csv"></label><p>Or paste CSV:</p><textarea id=t></textarea><label>Filter rows<input id=s placeholder="Type to filter"></label><button class=btn id=go>Show table</button></div><div class="card scroll" id=o aria-live=polite></div>`;
 let rows=[];const show=()=>{const f=$('#s').value.toLowerCase();$('#o').innerHTML=rows.length?`<p>${rows.length-1} data rows</p><div class=scroll><table><thead>${rows.slice(0,1).map(r=>`<tr>${r.map(c=>`<th scope=col>${esc(c)}</th>`).join('')}</tr>`).join('')}</thead><tbody>${rows.slice(1).map(r=>(!f||r.join(' ').toLowerCase().includes(f))?`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`:'').join('')}</tbody></table></div>`:'No data'};
 $('#fi').onchange=e=>loadTextFile(e.target.files[0],'#t');$('#go').onclick=()=>{try{rows=parseCSV($('#t').value);show()}catch(e){$('#o').textContent=e.message}};$('#s').oninput=show}
function csvJson(el){el.innerHTML=`<div class=card><input type=file id=fi accept=.csv><textarea id=t placeholder="Paste CSV (first row = headers)"></textarea><button class=btn id=go>Convert</button><button class="btn alt" id=dl>Download .json</button></div><pre id=o></pre>`;
 $('#fi').onchange=e=>loadTextFile(e.target.files[0],'#t');
 const conv=()=>{const r=parseCSV($('#t').value);if(!r.length)return'[]';const h=r[0];return JSON.stringify(r.slice(1).map(x=>Object.fromEntries(h.map((k,i)=>[k,x[i]??'']))),null,2)};
 const convert=()=>{try{return conv()}catch(e){return JSON.stringify({error:e.message})}};
 $('#go').onclick=()=>$('#o').textContent=convert();$('#dl').onclick=()=>download('data.json',convert(),'application/json')}
function excelTool(el){el.innerHTML=`<div class=card><label>Source<select id=src><option value="">CSV file / pasted text</option><option>expenses</option><option>clients</option><option>products</option><option>inventory</option><option>invoice</option></select></label><input type=file id=fi accept=.csv><textarea id=t placeholder="Paste CSV here"></textarea><button class=btn id=go>Download .xlsx</button></div>`;
 $('#fi').onchange=e=>loadTextFile(e.target.files[0],'#t');
 $('#go').onclick=async()=>{if(!await loadLibrary('xlsx'))return;const s=$('#src').value;let rows;if(s){const l=store.get(s);if(!l.length)return alert('No saved '+s+' yet.');const h=Object.keys(l[0]);rows=[h,...l.map(r=>h.map(k=>r[k]))]}else {try{rows=parseCSV($('#t').value)}catch(e){return alert(e.message)}}
  if(!rows.length)return alert('Nothing to export');const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(rows),'Sheet1');XLSX.writeFile(wb,'export.xlsx')}}
function pdfUtil(el){el.innerHTML=`<div class=card><h3>Merge PDFs</h3><input type=file id=m accept=.pdf multiple><button class=btn id=gm>Merge</button></div><div class=card><h3>Extract pages</h3><input type=file id=x accept=.pdf><input id=r placeholder="Pages e.g. 1-3,5"><button class=btn id=gx>Extract</button></div><p class=note id=msg>Files are processed in your browser and never uploaded.</p>`;
 const save=async d=>download('result.pdf',await d.save(),'application/pdf');
 $('#gm').onclick=async()=>{const files=[...$('#m').files];if(files.length<2)return alert('Choose 2+ PDFs');if(!await loadLibrary('pdflib'))return;const status=$('#msg');status.textContent='Merging PDFs…';try{const out=await PDFLib.PDFDocument.create();for(const f of files){const input=await PDFLib.PDFDocument.load(await readFile(f,'buf'));(await out.copyPages(input,input.getPageIndices())).forEach(p=>out.addPage(p))}await save(out);status.textContent='PDFs merged and downloaded.'}catch(e){status.textContent='Merge failed. Check that each file is a readable PDF.';alert('Could not merge PDFs: '+e.message)}};
 $('#gx').onclick=async()=>{const file=$('#x').files[0];if(!file)return alert('Choose a PDF');if(!await loadLibrary('pdflib'))return;const status=$('#msg');status.textContent='Extracting pages…';try{const source=await PDFLib.PDFDocument.load(await readFile(file,'buf')),indices=[];$('#r').value.split(',').forEach(part=>{const [first,last=first]=part.trim().split('-').map(Number);if(!Number.isInteger(first)||!Number.isInteger(last)||first>last)return;for(let page=first;page<=last&&page<=source.getPageCount();page++)if(page>0)indices.push(page-1)});if(!indices.length){status.textContent='Enter page numbers within the selected PDF.';return alert('Enter valid pages')}const out=await PDFLib.PDFDocument.create();(await out.copyPages(source,indices)).forEach(p=>out.addPage(p));await save(out);status.textContent='Selected pages extracted and downloaded.'}catch(e){status.textContent='Extraction failed. Check that the file is a readable PDF.';alert('Could not extract PDF pages: '+e.message)}}}
function ocrTool(el){el.innerHTML=`<div class=card><input type=file id=f accept=image/*><button class=btn id=go>Scan text</button><p class=note id=st>Choose a clear photo of a receipt (JPG/PNG). First scan downloads language data (needs internet).</p></div><div class=card><textarea id=o style="min-height:200px"></textarea><button class="btn alt" id=dl>Download .txt</button></div>`;
 $('#go').onclick=async()=>{if(!$('#f').files[0])return alert('Choose an image');if(!await loadLibrary('tesseract'))return;$('#st').textContent='Scanning…';
  try{const r=await Tesseract.recognize($('#f').files[0],'eng',{logger:m=>m.progress&&($('#st').textContent=m.status+' '+Math.round(m.progress*100)+'%')});$('#o').value=r.data.text;$('#st').textContent='Done. Check the text for mistakes.'}catch(e){$('#st').textContent='Scan failed: '+e.message}};
 $('#dl').onclick=()=>download('receipt.txt',$('#o').value)}
const paymentRows=inv=>inv.flatMap(r=>(Array.isArray(r.payments)?r.payments:[]).map(p=>({date:p.date||r.date,client:r.client||'Unassigned client',invoice:r.no||'',amount:Math.max(0,num(p.amount)),method:p.method||'Recorded payment'})).filter(p=>p.amount>0));
const getInvoices=()=>[...store.get('invoice'),...store.get('invoicepdf')].map(r=>({...r,total:docTotal(r),paidAmount:invoicePaid(r),balance:Math.max(0,docTotal(r)-invoicePaid(r)),status:invoiceStatus(r)}));
const inRange=(date,start,end)=>!!date&&date>=start&&date<=end;
function dateRange(preset,start,end){const d=new Date(),to=today();let from=to;if(preset==='week'){const day=(d.getDay()+6)%7;d.setDate(d.getDate()-day);from=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}else if(preset==='year')from=`${d.getFullYear()}-01-01`;else if(preset==='custom'){from=start||to;return{start:from,end:end||to}}else from=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-01`;return{start:from,end:to}}
function chartOptions(){return{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom'},tooltip:{mode:'index',intersect:false,callbacks:{label:ctx=>`${ctx.dataset.label||''}: ${money(ctx.parsed?.y??ctx.parsed)}`}}},interaction:{mode:'index',intersect:false},scales:{y:{beginAtZero:true,grid:{color:'#eaf0f4'},ticks:{callback:v=>money(v)}}}}}
function makeChart(id,type,data,options={}){const canvas=$('#'+id);if(!canvas||!window.Chart)return null;const base=chartOptions(),configured={...base,...options,plugins:{...base.plugins,...options.plugins},scales:options.scales??base.scales};const chart=new Chart(canvas,{type,data,options:configured});window.__iepCharts=(window.__iepCharts||[]).concat(chart);return chart}
function destroyCharts(){(window.__iepCharts||[]).forEach(c=>c.destroy());window.__iepCharts=[]}
function dateControls(prefix='dash'){return `<div class="dashboard-filters"><label>Date range<select id="${prefix}Range"><option value="month">This month</option><option value="week">This week</option><option value="year">This year</option><option value="custom">Custom</option></select></label><label>Start date<input id="${prefix}Start" type="date" aria-describedby="${prefix}DateError"></label><label>End date<input id="${prefix}End" type="date" aria-describedby="${prefix}DateError"></label><p class="date-error" id="${prefix}DateError" role="alert" hidden></p></div>`}
function attachDateControls(prefix,update){const preset=$('#'+prefix+'Range'),start=$('#'+prefix+'Start'),end=$('#'+prefix+'End'),error=$('#'+prefix+'DateError');const validate=(runUpdate=true)=>{const valid=validDateKey(start.value)&&validDateKey(end.value)&&start.value<=end.value;start.setCustomValidity(valid||!start.value?'':'Start date must be on or before the end date.');end.setCustomValidity(valid||!end.value?'':'End date must be on or after the start date.');error.hidden=valid;error.textContent=valid?'':'Choose valid dates, with the end date on or after the start date.';if(valid&&runUpdate)update();return valid};const setPreset=(runUpdate=true)=>{if(preset.value!=='custom'){const range=dateRange(preset.value);start.value=range.start;end.value=range.end}validate(runUpdate)};const useCustom=()=>{preset.value='custom'};start.onfocus=end.onfocus=useCustom;preset.onchange=setPreset;start.onchange=end.onchange=()=>{useCustom();validate()};setPreset(false);return()=>dateRange(preset.value,start.value,end.value)}
function dashboardPage(){destroyCharts();document.title='Business Dashboard – InvoiceExpensePro Tools';const app=$('#app');app.innerHTML=`<section class="hero"><h1>Business dashboard</h1><p>A clear view of recorded income, expenses and open invoices. Figures are calculated from records saved in this browser.</p></section><section class="card"><div class="bar"><div><h2>Financial overview</h2><p>Cash income includes recorded invoice payments only. Unpaid invoices are receivables, not income received. Display currency: ${esc(selectedCurrency()||'not set')} (format only; no conversion).</p></div>${dateControls()}</div></section><div id=dashContent></div>`;
 let hasChartData=false;const getRange=attachDateControls('dash',render);function render(){destroyCharts();const range=getRange(),allInv=getInvoices(),invs=allInv.filter(r=>inRange(r.date,range.start,range.end)),expenses=store.get('expenses').filter(r=>inRange(r.date,range.start,range.end)),payments=paymentRows(allInv).filter(r=>inRange(r.date,range.start,range.end));const income=payments.reduce((s,r)=>s+r.amount,0),expense=expenses.reduce((s,r)=>s+num(r.amount),0),open=invs.reduce((s,r)=>s+r.balance,0),overdue=invs.filter(r=>r.total>0&&r.balance>0&&r.due&&r.due<today()),paid=invs.filter(r=>r.total>0&&r.balance<.005),unpaid=invs.filter(r=>r.total>0&&r.balance>=.005),stock=store.get('inventory').reduce((s,r)=>s+Math.max(0,num(r.qty))*Math.max(0,num(r.cost)),0);hasChartData=payments.length>0||expenses.length>0||invs.some(i=>i.total>0);const recent=[...payments.map(p=>({...p,type:'Income'})),...expenses.map(e=>({date:e.date,client:e.desc||'Expense',amount:num(e.amount),type:'Expense'}))].sort((a,b)=>(b.date||'').localeCompare(a.date||'')).slice(0,8);
 $('#dashContent').innerHTML=`<div class="summary-grid"><div class=summary-card><small>Income received</small><strong>${money(income)}</strong><em>Recorded payments in range</em></div><div class=summary-card><small>Expenses</small><strong>${money(expense)}</strong><em>Saved expenses in range</em></div><div class=summary-card><small>Net cash movement</small><strong>${money(income-expense)}</strong><em>Income received less expenses</em></div><div class=summary-card><small>Outstanding invoices</small><strong>${money(open)}</strong><em>${unpaid.length} open · ${overdue.length} overdue</em></div><div class=summary-card><small>Paid invoices</small><strong>${paid.length}</strong><em>${unpaid.length} unpaid or partial</em></div><div class=summary-card><small>Inventory value</small><strong>${money(stock)}</strong><em>Current quantity × unit cost</em></div></div><div class="dashboard-grid" style="margin-top:16px"><section class=card><h2>Monthly income and expenses</h2>${payments.length||expenses.length?'<div class=chart-box><canvas id=dashTrend aria-label="Monthly income and expenses chart"></canvas></div><div class=chart-box><canvas id=dashProfit aria-label="Monthly cash profit trend chart"></canvas></div>':'<div class=empty-state>No cash activity recorded for this date range.</div>'}</section><section class=card><h2>Income versus expenses</h2>${payments.length||expenses.length?'<div class=chart-box><canvas id=dashCompare aria-label="Income versus expenses chart"></canvas></div>':'<div class=empty-state>No cash activity recorded for this date range.</div>'}</section><section class=card><h2>Expense categories</h2>${expenses.length?'<div class=chart-box><canvas id=dashCats aria-label="Expenses by category chart"></canvas></div>':'<div class=empty-state>No expenses recorded in this date range.</div>'}</section><section class=card><h2>Invoice status</h2>${invs.some(i=>i.total>0)?'<div class=chart-box><canvas id=dashStatus aria-label="Invoice status chart"></canvas></div>':'<div class=empty-state>No invoices issued in this date range.</div>'}</section><section class=card><h2>Recent transactions</h2>${recent.length?`<div class=scroll><table><thead><tr><th>Date</th><th>Type</th><th>Details</th><th>Amount</th></tr></thead><tbody>${recent.map(r=>`<tr><td>${esc(r.date||'')}</td><td>${r.type}</td><td>${esc(r.client||'')}</td><td>${money(r.amount)}</td></tr>`).join('')}</tbody></table></div>`:'<div class=empty-state>No income payments or expenses recorded in this date range.</div>'}</section></div><section class=card><h2>Quick actions</h2><a class="btn" href="#invoice">Create an invoice</a><a class="btn alt" href="#expenses">Add an expense</a><a class="btn alt" href="#reports">View reports</a></section>`;
  const buckets={},addBucket=(date,type,amount)=>{if(!validDateKey(date))return;const key=date.slice(0,7);buckets[key]??={income:0,expense:0};buckets[key][type]+=amount};payments.forEach(p=>addBucket(p.date,'income',p.amount));expenses.forEach(e=>addBucket(e.date,'expense',num(e.amount)));const labels=Object.keys(buckets).sort();if(labels.length&&(payments.length||expenses.length)){makeChart('dashTrend','line',{labels,datasets:[{label:'Income received',data:labels.map(k=>buckets[k].income),borderColor:'#087f74',backgroundColor:'#087f7420',fill:true,tension:.3},{label:'Expenses',data:labels.map(k=>buckets[k].expense),borderColor:'#d27a4b',backgroundColor:'#d27a4b20',fill:true,tension:.3}]});makeChart('dashProfit','line',{labels,datasets:[{label:'Net cash profit / (loss)',data:labels.map(k=>buckets[k].income-buckets[k].expense),borderColor:'#173c62',backgroundColor:'#173c6220',fill:true,tension:.3}]});makeChart('dashCompare','bar',{labels:['Selected range'],datasets:[{label:'Income received',data:[income],backgroundColor:'#087f74',borderRadius:6},{label:'Expenses',data:[expense],backgroundColor:'#d27a4b',borderRadius:6}]})}if(expenses.length){const cats={};expenses.forEach(e=>cats[e.category||'Uncategorized']=(cats[e.category||'Uncategorized']||0)+num(e.amount));makeChart('dashCats','doughnut',{labels:Object.keys(cats),datasets:[{data:Object.values(cats),backgroundColor:['#087f74','#173c62','#d27a4b','#77a6a3','#7c85b7','#d6b85b','#9b6c9a']}]},{scales:{}})}if(invs.some(i=>i.total>0))makeChart('dashStatus','bar',{labels:['Paid','Unpaid','Overdue'],datasets:[{label:'Invoices',data:[paid.filter(i=>i.total>0).length,unpaid.filter(i=>i.total>0&&!i.due||i.total>0&&i.due>=today()).length,overdue.filter(i=>i.total>0).length],backgroundColor:['#087f74','#d6b85b','#b93838'],borderRadius:6}]},{plugins:{legend:{display:false}}})
  if(hasChartData&&!window.Chart)loadLibrary('chart').then(ok=>{if(ok&&app.isConnected)render()});};render()}
const REPORT_TYPES=[['income','Income Report'],['expenses','Expense Report'],['pnl','Profit and Loss'],['cashflow','Cash Flow'],['status','Invoice Status'],['receivable','Outstanding and Overdue'],['categories','Expense Categories'],['summary','Monthly and Yearly Summary'],['clients','Client Billing'],['inventory','Inventory Summary']];
const COUNT_LABELS=new Set(['Payments','Expense records','Paid','Unpaid / partial','Overdue invoices','Categories','Clients billed','Items','Units in stock']);
function reports(el){destroyCharts();el.innerHTML=`<section class="card"><div class=bar><div><h2>Reports & Analytics</h2><p>Reports use saved invoice payments and expenses. Issued invoice totals are separate from cash received. Display currency: ${esc(selectedCurrency()||'not set')} (format only; no conversion).</p></div></div><div class=grid><label>Report<select id=reportType>${REPORT_TYPES.map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></label>${dateControls('report')}<label id=periodWrap hidden>Group by<select id=reportPeriod><option value="month">Month</option><option value="year">Year</option></select></label></div><div class=bar><span><button class="btn alt" id=reportCsv>Export CSV</button><button class="btn alt" id=reportXlsx>Export spreadsheet</button><button class="btn" id=reportPrint>Print / Save PDF</button></span></div></section><section id=reportContent></section>`;
 let currentRows=[],currentHead=[];const type=$('#reportType'),getRange=attachDateControls('report',render);type.onchange=()=>{$('#periodWrap').hidden=type.value!=='summary';render()};$('#reportPeriod').onchange=render;function render(){destroyCharts();const {start,end}=getRange(),kind=type.value,allInv=getInvoices(),inv=allInv.filter(r=>inRange(r.date,start,end)),expenses=store.get('expenses').filter(r=>inRange(r.date,start,end)),payments=paymentRows(allInv).filter(r=>inRange(r.date,start,end));let title='',cards=[],heads=[],rows=[],note='';
  const income=payments.reduce((s,r)=>s+r.amount,0),cost=expenses.reduce((s,r)=>s+num(r.amount),0),cashRows=[...payments.map(p=>[p.date,'Income',p.client,p.invoice,p.amount]),...expenses.map(e=>[e.date,'Expense',e.desc||'',e.category||'',num(e.amount)])].sort((a,b)=>String(a[0]).localeCompare(String(b[0])));
  if(kind==='income'){title='Income received';heads=['Date','Client','Invoice','Payment method','Amount'];rows=payments.map(p=>[p.date,p.client,p.invoice,p.method,p.amount]);cards=[['Total received',income],['Payments',payments.length]];note='Only recorded payments count as income. An issued invoice without a recorded payment is excluded.'}
  if(kind==='expenses'){title='Expenses';heads=['Date','Description','Category','Amount'];rows=expenses.map(e=>[e.date,e.desc,e.category,e.amount]);cards=[['Total expenses',cost],['Expense records',expenses.length]]}
  if(kind==='pnl'){title='Profit and loss (cash basis)';heads=['Metric','Amount'];rows=[['Income received',income],['Expenses',cost],['Net profit / (loss)',income-cost]];cards=[['Income received',income],['Expenses',cost],['Net profit / (loss)',income-cost]];note='Cash-basis view: income is recorded invoice payments, not the face value of issued unpaid invoices.'}
  if(kind==='cashflow'){title='Cash flow';heads=['Date','Type','Description','Reference / category','Amount'];rows=cashRows;cards=[['Cash in',income],['Cash out',cost],['Net cash flow',income-cost]]}
  if(kind==='status'){title='Invoice status';heads=['Invoice','Client','Issued','Due','Invoice total','Paid','Balance','Status'];rows=inv.map(r=>[r.no,r.client,r.date,r.due,money(r.total),money(r.paidAmount),money(r.balance),r.status]);cards=[['Issued invoice value',inv.reduce((s,r)=>s+r.total,0)],['Paid',inv.filter(r=>r.total>0&&r.balance<.005).length],['Unpaid / partial',inv.filter(r=>r.total>0&&r.balance>=.005).length]]}
  if(kind==='receivable'){title='Outstanding and overdue invoices';heads=['Invoice','Client','Issued','Due','Invoice total','Paid','Balance','Status'];rows=inv.filter(r=>r.balance>=.005).map(r=>[r.no,r.client,r.date,r.due,money(r.total),money(r.paidAmount),money(r.balance),r.status]);const overdue=inv.filter(r=>r.balance>=.005&&r.due&&r.due<today());cards=[['Open receivables',inv.filter(r=>r.balance>=.005).reduce((s,r)=>s+r.balance,0)],['Overdue amount',overdue.reduce((s,r)=>s+r.balance,0)],['Overdue invoices',overdue.length]]}
  if(kind==='categories'){title='Expenses by category';const groups={};expenses.forEach(e=>groups[e.category||'Uncategorized']=(groups[e.category||'Uncategorized']||0)+num(e.amount));heads=['Category','Expense total','Share of expenses'];rows=Object.entries(groups).map(([k,v])=>[k,money(v),cost?v/cost*100+'%':'0%']);cards=[['Expense total',cost],['Categories',Object.keys(groups).length]];if(rows.length)note='Category share is calculated from expenses recorded inside the selected date range.'}
  if(kind==='summary'){const period=$('#reportPeriod').value;title=`${period==='year'?'Yearly':'Monthly'} financial summary`;const groups={};cashRows.forEach(r=>{const key=String(r[0]||'').slice(0,period==='year'?4:7);if(!key)return;groups[key]??={income:0,expense:0};groups[key][r[1]==='Income'?'income':'expense']+=num(r[4])});heads=[period==='year'?'Year':'Month','Income received','Expenses','Net profit / (loss)'];rows=Object.entries(groups).sort(([a],[b])=>a.localeCompare(b)).map(([k,v])=>[k,money(v.income),money(v.expense),money(v.income-v.expense)]);cards=[['Income received',income],['Expenses',cost],['Net profit / (loss)',income-cost]];note=`${period==='year'?'Yearly':'Monthly'} totals follow recorded payment dates and expense dates.`}
  if(kind==='clients'){title='Client billing';const group={};inv.forEach(r=>{const k=r.client||'Unassigned client';group[k]??={invoiced:0,paid:0,balance:0,count:0};group[k].invoiced+=r.total;group[k].paid+=r.paidAmount;group[k].balance+=r.balance;group[k].count++});heads=['Client','Invoices','Invoiced','Paid','Outstanding'];rows=Object.entries(group).map(([k,v])=>[k,v.count,money(v.invoiced),money(v.paid),money(v.balance)]);cards=[['Clients billed',Object.keys(group).length],['Invoiced',inv.reduce((s,r)=>s+r.total,0)],['Outstanding',inv.reduce((s,r)=>s+r.balance,0)]];note='Invoice values are issued amounts; paid values include recorded payments only.'}
  if(kind==='inventory'){title='Inventory summary';const stock=store.get('inventory');heads=['SKU','Item','Quantity','Unit cost','Stock value'];rows=stock.map(r=>[r.sku,r.name,r.qty,money(r.cost),money(Math.max(0,num(r.qty))*Math.max(0,num(r.cost)))]);cards=[['Items',stock.length],['Units in stock',stock.reduce((s,r)=>s+Math.max(0,num(r.qty)),0)],['Stock value',stock.reduce((s,r)=>s+Math.max(0,num(r.qty))*Math.max(0,num(r.cost)),0)]];note='Inventory is a current snapshot because stock records do not include movement dates; the selected date range does not filter it.'}
  if(kind==='pnl'&&!payments.length&&!expenses.length)rows=[];currentHead=heads;currentRows=rows;const hasRows=rows.length>0;$('#reportContent').innerHTML=`<div class=card><div class=bar><div><h2>${title}</h2><p>${esc(start)} to ${esc(end)}</p></div></div><div class=summary-grid>${cards.map(([k,v])=>`<div class=summary-card><small>${k}</small><strong>${typeof v==='number'&&!COUNT_LABELS.has(k)?money(v):v}</strong></div>`).join('')}</div>${note?`<p class=note>${note}</p>`:''}${hasRows?`<label>Search rows<input id=reportSearch type=search placeholder="Filter this report"></label><div class=scroll style="margin-top:12px"><table><thead><tr>${heads.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody id=reportBody>${tableRows(rows)}</tbody></table></div>`:'<div class=empty-state>No records are available for this report and date range.</div>'}${(kind==='pnl'||kind==='cashflow')&&hasRows?'<div class=chart-box style="margin-top:20px"><canvas id=reportChart aria-label="Income and expense comparison chart"></canvas></div>':''}</div>`;
  if(hasRows)$('#reportSearch').oninput=e=>{$('#reportBody').innerHTML=tableRows(rows.filter(r=>r.join(' ').toLowerCase().includes(e.target.value.toLowerCase())))};if((kind==='pnl'||kind==='cashflow')&&hasRows)makeChart('reportChart','bar',{labels:['Selected period'],datasets:[{label:'Income received',data:[income],backgroundColor:'#087f74'},{label:'Expenses',data:[cost],backgroundColor:'#d27a4b'}]},{plugins:{legend:{position:'bottom'}}});if((kind==='pnl'||kind==='cashflow')&&hasRows&&!window.Chart)loadLibrary('chart').then(ok=>{if(ok&&el.isConnected)render()});
 };
 function tableRows(rows){return rows.map(r=>`<tr>${r.map(v=>`<td>${esc(v??'')}</td>`).join('')}</tr>`).join('')}
 $('#reportCsv').onclick=()=>download('invoiceexpensepro-report.csv',toCSV([currentHead,...currentRows]),'text/csv');$('#reportXlsx').onclick=async()=>{if(!await loadLibrary('xlsx'))return;const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet([currentHead,...currentRows]),'Report');XLSX.writeFile(wb,'invoiceexpensepro-report.xlsx')};$('#reportPrint').onclick=()=>print();render();}
function report(el){const inv=getInvoices(),expenses=store.get('expenses'),clients=store.get('clients'),inventory=store.get('inventory'),income=paymentRows(inv).reduce((s,p)=>s+p.amount,0),cost=expenses.reduce((s,r)=>s+num(r.amount),0),outstanding=inv.reduce((s,r)=>s+r.balance,0),stock=inventory.reduce((s,r)=>s+Math.max(0,num(r.qty))*Math.max(0,num(r.cost)),0);el.innerHTML=`<div class=card><h2>Business summary · ${today()}</h2><p>Income reflects recorded payments only; open invoice values are shown separately.</p><div class=summary-grid><div class=summary-card><small>Income received</small><strong>${money(income)}</strong></div><div class=summary-card><small>Expenses</small><strong>${money(cost)}</strong></div><div class=summary-card><small>Cash profit / (loss)</small><strong>${money(income-cost)}</strong></div><div class=summary-card><small>Open receivables</small><strong>${money(outstanding)}</strong></div><div class=summary-card><small>Clients</small><strong>${clients.length}</strong></div><div class=summary-card><small>Stock value</small><strong>${money(stock)}</strong></div></div><p class=note>Cash profit is recorded payments less saved expenses. Issued unpaid invoices are not counted as cash income.</p><button class=btn id=printSummary>Print / Save PDF</button><button class="btn alt" id=summaryJson>Download JSON</button><a class="btn alt" href="#reports">Open Reports & Analytics</a></div>`;$('#printSummary').onclick=()=>print();$('#summaryJson').onclick=()=>download('business-summary.json',JSON.stringify({date:today(),incomeReceived:income,expenses:cost,cashProfit:income-cost,openReceivables:outstanding,clients:clients.length,stockValue:stock},null,2),'application/json')}

/* ---------- Tool list: [id, category, icon, name, description, builder(el)] ---------- */
const CATS=['Invoice & Billing','Finance','Business Calculators','Business Management','Document & File Tools'];
const ICON_PATHS={0:'<path d="M7 3.75h7l4.5 4.5v12A1.75 1.75 0 0 1 16.75 22h-9.5A1.75 1.75 0 0 1 5.5 20.25V5.5A1.75 1.75 0 0 1 7.25 3.75Z"/><path d="M14 4v5h5M8.5 13h7M8.5 16.5h7"/>',1:'<path d="M4 19.5h16"/><path d="m6 15 4-4 3 2 5-6"/><path d="M15 7h3v3"/>',2:'<rect x="5" y="3.5" width="14" height="17" rx="2"/><path d="M8 7h8M8 11h2m4 0h2m-8 4h2m4 0h2m-8 3h2m4 0h2"/>',3:'<rect x="3.5" y="7" width="17" height="13" rx="2"/><path d="M8 7V5.5A1.5 1.5 0 0 1 9.5 4h5A1.5 1.5 0 0 1 16 5.5V7m-12 5h16m-11 0v2h6v-2"/>',4:'<path d="M4 5.5A1.5 1.5 0 0 1 5.5 4H10l2 2h6.5A1.5 1.5 0 0 1 20 7.5v11a1.5 1.5 0 0 1-1.5 1.5h-13A1.5 1.5 0 0 1 4 18.5z"/><path d="M4 9h16"/>'};
const iconSvg=category=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${ICON_PATHS[category]}</svg>`;
const CALC_VALIDATORS={profit:v=>v.rev>=0&&v.cost>=0&&v.exp>=0,loss:v=>v.buy>=0&&v.sell>=0&&v.qty>0,budget:v=>Object.values(v).every(n=>n>=0),cashflow:v=>v.in>=0&&v.out>=0,breakeven:v=>v.fixed>=0&&v.price>0&&v.var>=0,savings:v=>v.goal>=0&&v.cur>=0&&v.mon>=0&&v.rate>=0,tax:v=>v.amt>=0&&v.rate>=0,discount:v=>v.p>=0&&v.d>=0&&v.d<=100,markup:v=>v.c>=0&&v.m>=0,margin:v=>v.p>=0&&v.c>=0,commission:v=>v.s>=0&&v.r>=0&&v.b>=0,loan:v=>v.p>=0&&v.r>=0&&v.y>0,salary:v=>v.g>=0&&v.t>=0&&v.t<=100&&v.a>=0&&v.d>=0};
const C=id=>el=>calc(el,CALCS[id][0],CALCS[id][1],CALC_VALIDATORS[id]);
const TOOLS=[
['invoice',0,'🧾','Invoice Generator','Create, edit and save invoices with tax and discount.',el=>docTool(el,'invoice','Invoice')],
['quote',0,'📝','Quote Maker','Make price quotes for clients.',el=>docTool(el,'quote','Quote')],
['receipt',0,'🧷','Receipt Maker','Issue sales receipts.',el=>docTool(el,'receipt','Receipt')],
['invoicepdf',0,'📄','Invoice PDF Generator','Create invoices and download each as a PDF.',el=>docTool(el,'invoicepdf','Invoice')],
['payreceipt',0,'💳','Payment Receipt Generator','Confirm a payment received.',el=>docTool(el,'payreceipt','Payment Receipt',[['method','Payment method','select',['Cash','Bank transfer','Card','Cheque','Other']]])],
['recurring',0,'🔁','Recurring Invoice Planner','Plan repeating invoices and see next due dates.',el=>crud(el,{key:'recurring',title:'recurring invoice',pdf:true,docTitle:'Invoice',total:docTotal,cols:['no','client','date','freq','total'],validate:validateDocument,validateShowsMessage:true,
  fields:[['no','Number','text'],['client','Client','text'],['date','First invoice date','date'],['freq','Repeats','select',['Weekly','Monthly','Quarterly','Yearly']],['items','Items: description | qty | price','area'],['tax','Tax %','number'],['discType','Discount type','select',['Percent','Fixed']],['disc','Discount amount / %','number'],['notes','Notes','area']],
  extra:r=>{const d=nextRecurringDate(r.date,r.freq);return ` <small>Next: ${d?dateKey(d):'–'}</small>`}})],
['expenses',1,'💸','Expense Tracker','Record expenses, see category chart, export.',el=>crud(el,{key:'expenses',title:'expense',sum:'amount',chart:'category',cols:['date','desc','category','amount'],validate:r=>num(r.amount)>=0,fields:[['date','Date','date'],['desc','Description','text'],['category','Category','select',['Office','Travel','Food','Software','Marketing','Utilities','Salary','Other']],['amount','Amount','number']]})],
['profit',1,'📈','Profit Calculator','Net profit and margin.',C('profit')],
['loss',1,'📉','Loss Calculator','Loss amount and percentage.',C('loss')],
['budget',1,'🧮','Budget Planner','Plan monthly spending and savings.',C('budget')],
['cashflow',1,'🌊','Cash Flow Calculator','Net cash flow and closing balance.',C('cashflow')],
['breakeven',1,'⚖️','Break-Even Calculator','Units needed to cover costs.',C('breakeven')],
['savings',1,'🐖','Savings Planner','Months needed to reach a goal.',C('savings')],
['tax',2,'🏛️','Tax Calculator','Add or remove tax from an amount.',C('tax')],
['discount',2,'🏷️','Discount Calculator','Final price after discount.',C('discount')],
['markup',2,'⬆️','Markup Calculator','Selling price from cost and markup.',C('markup')],
['margin',2,'📊','Profit Margin Calculator','Margin and markup from price and cost.',C('margin')],
['commission',2,'🤝','Commission Calculator','Commission and total earnings.',C('commission')],
['loan',2,'🏦','Loan Repayment Calculator','Monthly payment and interest.',C('loan')],
['clients',3,'👥','Client Manager','Save client contacts.',el=>crud(el,{key:'clients',title:'client',cols:['name','email','phone','company'],fields:[['name','Name','text'],['email','Email','email'],['phone','Phone','text'],['company','Company','text'],['address','Address','text']]})],
['products',3,'🛍️','Product & Service Manager','Keep a price list.',el=>crud(el,{key:'products',title:'product / service',cols:['name','type','price'],validate:r=>num(r.price)>=0,fields:[['name','Name','text'],['type','Type','select',['Product','Service']],['price','Price','number'],['desc','Description','text']]})],
['inventory',3,'📦','Inventory Tracker','Track stock quantity and value.',el=>crud(el,{key:'inventory',title:'stock item',cols:['sku','name','qty','cost','total'],validate:r=>num(r.qty)>=0&&num(r.cost)>=0,fields:[['sku','SKU','text'],['name','Item','text'],['qty','Quantity','number'],['cost','Unit cost','number']],
  total:r=>num(r.qty)*num(r.cost)})],
['po',3,'📬','Purchase Order Generator','Create purchase orders for suppliers.',el=>docTool(el,'po','Purchase Order')],
['salary',3,'💼','Salary Calculator','Net pay after tax and deductions.',C('salary')],
['report',3,'📑','Business Report Generator','Summary from your saved data; print or export.',report],
['reports',3,'📊','Reports & Analytics','Explore income, expenses, receivables, cash flow and inventory reports.',reports],
['csvview',4,'🗂️','CSV Viewer','Open and filter CSV files.',csvViewer],
['csvjson',4,'🔄','CSV-to-JSON Converter','Convert CSV into JSON.',csvJson],
['excel',4,'📗','Excel Export Tool','Turn CSV or saved data into .xlsx.',excelTool],
['pdfutil',4,'📕','PDF Utility','Merge PDFs or extract pages.',pdfUtil],
['ocr',4,'🔍','Receipt OCR Scanner','Read text from receipt photos.',ocrTool]];

/* ---------- Router & home page ---------- */
let cat=-1;
function toolDirectory(){const q=$('#q').value.toLowerCase();
 const groups=CATS.map((c,ci)=>{const l=TOOLS.filter(t=>t[1]==ci&&(cat<0||cat==ci)&&(t[3]+t[4]).toLowerCase().includes(q));
  return l.length?`<h2 class=cat>${c}</h2><div class="cards cat-${ci}">${l.map(t=>`<a class=tool href="#${t[0]}"><span class=ic>${iconSvg(t[1])}</span><b>${t[3]}</b><small>${t[4]}</small></a>`).join('')}</div>`:''}).join('');
 $('#app').innerHTML=`<div class=hero><h1>31 practical tools for invoices, expenses & business</h1><p>Everything runs in your browser. No sign-up. Your data stays on your device.</p></div>
 <div class=chips role=group aria-label="Filter tools by category">${['All',...CATS].map((c,i)=>`<button type=button class="chip ${cat==i-1?'on':''}" aria-pressed="${cat==i-1}" data-c=${i-1}>${c}</button>`).join('')}</div>`+(groups||'<p class="card" role="status">No tools match your search. Try another keyword or choose a different category.</p>');
 document.querySelectorAll('.chip').forEach(c=>c.onclick=()=>{cat=+c.dataset.c;toolDirectory()});document.title='InvoiceExpensePro Tools – Free Business Tools'}
const INFO_PAGES={contact:{title:'Contact',body:'<p>No contact address or contact form has been configured for this website.</p>'},privacy:{title:'Privacy Policy',body:'<h2>Data stored in your browser</h2><p>Business records and your display-currency preference are saved in this browser on this device using local storage. The app has no account system, application server, or device-sync service. Use the backup controls in the footer to export or restore your records.</p><h2>Files and optional libraries</h2><p>PDF, spreadsheet, chart, and receipt-reading features load their supporting libraries from third-party CDNs when needed. The tools process selected files in your browser. Your records are not sent to an InvoiceExpensePro server.</p><h2>Deleting data</h2><p>You can delete saved app data from the footer. Clearing this browser’s site data also removes locally saved records.</p>'},terms:{title:'Terms of Use',body:'<p>InvoiceExpensePro Tools provides general-purpose document and business calculation utilities. Review generated documents and results before relying on or sharing them.</p><p>Tax, loan, profit, and other financial calculations are estimates based on values you enter. They do not replace professional accounting, tax, legal, or financial advice. Tax rules and business requirements vary.</p><p>You are responsible for keeping backups of records stored in your browser. The app does not synchronize records between devices or provide automated reminders.</p>'}};
function infoPage(key){const page=INFO_PAGES[key];if(!page)return dashboardPage();$('#app').innerHTML=`<a class=back href="#dashboard">← Dashboard</a><article class="card info-page"><h1>${page.title}</h1>${page.body}</article>`;document.title=page.title+' – InvoiceExpensePro Tools'}
function route(){const key=location.hash.slice(1);if(!key||key==='dashboard')return dashboardPage();if(key==='tools')return toolDirectory();if(INFO_PAGES[key])return infoPage(key);const t=TOOLS.find(t=>t[0]===key);if(!t)return dashboardPage();
 $('#app').innerHTML=`<a class=back href="#tools">← All tools</a><h1 class=page-title><span class=page-icon>${iconSvg(t[1])}</span>${t[3]}</h1><p>${t[4]}</p><div id=tool></div>`;document.title=t[3]+' – InvoiceExpensePro Tools';t[5]($('#tool'))}
addEventListener('DOMContentLoaded',()=>{
 $('#q').oninput=()=>{cat=-1;if(location.hash!=='#tools')location.hash='#tools';else toolDirectory()};addEventListener('hashchange',route);
 $('#footerYear').textContent=new Date().getFullYear();document.querySelectorAll('[data-footer-category]').forEach(link=>link.onclick=()=>{cat=Number(link.dataset.footerCategory);if(location.hash==='#tools')toolDirectory()});
 const currency=$('#currency');currency.value=selectedCurrency();currency.onchange=()=>{try{localStorage.setItem('iep_currency',currency.value);if(['','#dashboard','#tools','#reports','#report'].includes(location.hash))route()}catch{alert('Could not save the currency preference in this browser.')}};
 $('#expAll').onclick=()=>{const o={};Object.keys(localStorage).filter(k=>k.startsWith('iep_')).forEach(k=>{try{o[k]=JSON.parse(localStorage[k])}catch{o[k]=localStorage[k]}});download('invoiceexpensepro-backup.json',JSON.stringify(o,null,2),'application/json')};
 $('#pickImport').onclick=()=>$('#importFile').click();$('#importFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const backup=JSON.parse(await readFile(file));if(!backup||Array.isArray(backup)||typeof backup!=='object')throw new Error('Backup must be a JSON object.');const entries=Object.entries(backup);if(!entries.length||entries.some(([k,v])=>!k.startsWith('iep_')||(k==='iep_currency'?typeof v!=='string'||!CURRENCIES.has(v):!Array.isArray(v))))throw new Error('Backup has an unsupported or invalid data format.');if(!confirm('Import this backup and replace the InvoiceExpensePro data currently saved in this browser?'))return;const existing=Object.keys(localStorage).filter(k=>k.startsWith('iep_')),snapshot=Object.fromEntries(existing.map(k=>[k,localStorage.getItem(k)]));try{existing.forEach(k=>localStorage.removeItem(k));entries.forEach(([k,v])=>localStorage.setItem(k,k==='iep_currency'?v:JSON.stringify(v)));currency.value=selectedCurrency();route();alert('Backup imported successfully.')}catch(err){Object.keys(localStorage).filter(k=>k.startsWith('iep_')).forEach(k=>localStorage.removeItem(k));Object.entries(snapshot).forEach(([k,v])=>localStorage.setItem(k,v));throw err}}catch(err){alert('Could not import backup: '+err.message)}finally{e.target.value=''}};
 $('#delAll').onclick=()=>{if(confirm('Permanently delete ALL saved data in this browser?')){Object.keys(localStorage).filter(k=>k.startsWith('iep_')).forEach(k=>localStorage.removeItem(k));route()}};route()});
